package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the statement taken in the audit file, with the due-total as the screen shows it (n/a when none). */
public class AuditStatement {
    public void audit(@Val StatementRequest request, @Val Statement statement, Audit audit) {
        audit.record("STATEMENT sheet=" + statement.sheetId() + " by=" + request.user()
                + " name=" + statement.name()
                + " due-total=" + (statement.dueTotal() != null ? statement.dueTotal().toPlainString() : "n/a")
                + " claims=" + statement.claims());
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.rate.RateRepository;

/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, else
     *  live: its amount times its person's grade rate in force on its date, divided by 100, rounded half to
     *  even to two decimals; null (n/a) when no rate applies. */
    public static BigDecimal figure(Claim claim, String grade, RateRepository rates) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.statedDue() != null) {
            return claim.statedDue();
        }
        return rates.on(claim.sheetId(), grade, claim.date())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }

    /** A person's due-total: the figures of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade has no rate today, unless a claim that counts keeps a figure (settled or stated). */
    public static BigDecimal total(String sheetId, List<Claim> claims, String grade, LocalDate today, RateRepository rates) {
        List<Claim> counted = claims.stream().filter(c -> c.status().counts()).toList();
        boolean kept = counted.stream().anyMatch(c -> c.settledDue() != null || c.statedDue() != null);
        if (!kept && rates.on(sheetId, grade, today).isEmpty()) {
            return null;
        }
        return counted.stream().map(c -> figure(c, grade, rates)).filter(f -> f != null)
                .reduce(new BigDecimal("0.00"), BigDecimal::add);
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonResponse;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Take the person's statement: record their due-total now and the sheet's today, bind each of their claims
 *  that counts to the figure it shows now, and unbind the rest (their due is live again). A settled claim's
 *  fixed due is left as it is. */
public class SaveStatement {
    public void save(@Val Person loaded, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Out<Statement> statement, Out<PersonResponse> saved) {
        people.lock(loaded);
        Person person = people.find(loaded.sheetId(), loaded.id());
        var today = sheets.today(person.sheetId());
        List<Claim> theirs = claims.listForPerson(person.sheetId(), person.id());
        BigDecimal total = Dues.total(person.sheetId(), theirs, person.grade(), today, rates);
        int counted = 0;
        for (Claim c : theirs) {
            if (c.status().counts()) {
                counted++;
                claims.state(c, true, Dues.figure(c, person.grade(), rates));
            } else if (c.stated()) {
                claims.state(c, false, null);
            }
        }
        people.stated(person, total, today);
        statement.set(new Statement(person.sheetId(), person.name(), total, counted));
        saved.set(PersonResponse.from(people.find(person.sheetId(), person.id())));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;

/** A statement taken of a person: their name, due-total then (null: n/a) and how many of their claims counted. */
public record Statement(String sheetId, String name, BigDecimal dueTotal, int claims) {
}
package net.officefloor.hq.app.statement;

/** Body of taking a person's statement: who is taking it. */
public record StatementRequest(String user) {
}
package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user. Publishes the user trimmed. */
public class ValidateStatement {
    public void validate(@RequestBody StatementRequest request, Out<StatementRequest> body)
            throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before taking a statement.");
        }
        body.set(new StatementRequest(request.user().trim()));
    }
}
